patch('cause_line', 'if(k!=="ok"&&r.error_short){tt.appendChild(el("small",null,r.error_short))}', 'if(k!=="ok"){tt.appendChild(el("small",{"class":"cause"},causeLine(r)))}if(k!=="ok"&&r.error_short){tt.appendChild(el("small",null,r.error_short))}');
