patch('cost_runs', '"data-k":"Kosten"},fmtUsd(r.cost_usd))', '"data-k":"Kosten",title:r.cost_usd==null?"Für diesen Lauf wurden keine Kosten protokolliert":""},r.cost_usd==null?"nicht erfasst":fmtUsd(r.cost_usd))');
