  daily,
  customers: customers.map(c => ({ code: c.code, name: c.name })),
};
const COST_JS = '<script>\n(function(){"use strict";\n' +
  'var K=/*__KOSTEN__*/null;if(!K)return;\n' + ROLE_FN +
  'var $=function(s){return document.querySelector(s)};\n' +
  'var el=function(t,a,x){var e=document.createElement(t);if(a)for(var k in a)e.setAttribute(k,a[k]);if(x!=null)e.textContent=x;return e};\n' +
  'var tz={timeZone:"Europe/Berlin"};\n' +
  'var usd=function(v,d){return v==null?"nicht erfasst":Number(v).toLocaleString("de-DE",{minimumFractionDigits:d==null?4:d,maximumFractionDigits:d==null?4:d})+" $"};\n' +
  'var eur=function(v,d){return v==null||!K.usd_eur_rate?"nicht erfasst":(Number(v)*K.usd_eur_rate).toLocaleString("de-DE",{minimumFractionDigits:d==null?4:d,maximumFractionDigits:d==null?4:d})+" €"};\n' +
